PRAGMA foreign_keys=ON;
UPDATE platform_schema_metadata SET schema_contract_version=2 WHERE singleton_id=1 AND schema_contract_version=1;
CREATE TABLE intelligence_rights_schedules(environment_id TEXT NOT NULL,schedule_id TEXT NOT NULL,contract_version TEXT NOT NULL CHECK(contract_version='intelligence-retention/1'),source_class TEXT NOT NULL CHECK(source_class IN('synthetic_project_owned','manual_user_owned')),schedule_jcs TEXT NOT NULL CHECK(length(schedule_jcs)<=8192),created_at TEXT NOT NULL,PRIMARY KEY(environment_id,schedule_id));
CREATE TABLE intelligence_keys(environment_id TEXT NOT NULL,key_id TEXT NOT NULL,algorithm TEXT NOT NULL CHECK(algorithm='HMAC-SHA-256'),metadata_version TEXT NOT NULL CHECK(metadata_version='intelligence-key-metadata/2'),activates_at TEXT NOT NULL,created_at TEXT NOT NULL,identity_jcs TEXT NOT NULL CHECK(length(identity_jcs)<=2048),PRIMARY KEY(environment_id,key_id));
CREATE TABLE intelligence_key_status_events(environment_id TEXT NOT NULL,event_id TEXT NOT NULL,key_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('active','verify-only','revoked','unavailable')),effective_at TEXT NOT NULL,prior_event_id TEXT,reason_ref TEXT NOT NULL,issuer_ref TEXT NOT NULL,PRIMARY KEY(environment_id,event_id),UNIQUE(environment_id,key_id,event_id),FOREIGN KEY(environment_id,key_id) REFERENCES intelligence_keys(environment_id,key_id),FOREIGN KEY(environment_id,key_id,prior_event_id) REFERENCES intelligence_key_status_events(environment_id,key_id,event_id));
CREATE INDEX intelligence_key_status_order ON intelligence_key_status_events(environment_id,key_id,effective_at DESC,event_id DESC);
CREATE VIEW intelligence_current_key_status AS SELECT e.environment_id,e.key_id,e.event_id,e.status,e.effective_at,e.effective_at status_effective_at FROM intelligence_key_status_events e WHERE NOT EXISTS(SELECT 1 FROM intelligence_key_status_events n WHERE n.environment_id=e.environment_id AND n.key_id=e.key_id AND (n.effective_at>e.effective_at OR (n.effective_at=e.effective_at AND n.event_id>e.event_id)));
CREATE TABLE authenticated_intelligence_records(environment_id TEXT NOT NULL,record_id TEXT NOT NULL,stream_id TEXT NOT NULL,record_type TEXT NOT NULL CHECK(record_type IN('market_observation','canonical_result_observation')),schema_version TEXT NOT NULL CHECK(schema_version='mk-intelligence-record-jcs/1'),contract_version TEXT NOT NULL CHECK(contract_version='authenticated-intelligence-record/1'),rights_schedule_id TEXT NOT NULL,key_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,content_hash TEXT NOT NULL,authentication_tag TEXT NOT NULL,header_jcs TEXT NOT NULL CHECK(length(header_jcs)<=8192),payload_jcs TEXT NOT NULL CHECK(length(payload_jcs)<=49152),declared_parent_count INTEGER NOT NULL CHECK(declared_parent_count IN(0,1)),parent_head_id TEXT,corrects_record_id TEXT,issued_at TEXT NOT NULL,validated_at TEXT NOT NULL,project_delete_after TEXT,hard_source_delete_after TEXT,indefinite_basis TEXT,PRIMARY KEY(environment_id,record_id),UNIQUE(environment_id,idempotency_key),UNIQUE(environment_id,content_hash,record_type),UNIQUE(environment_id,record_id,stream_id,record_type),FOREIGN KEY(environment_id,rights_schedule_id) REFERENCES intelligence_rights_schedules(environment_id,schedule_id),FOREIGN KEY(environment_id,key_id) REFERENCES intelligence_keys(environment_id,key_id),FOREIGN KEY(environment_id,parent_head_id) REFERENCES authenticated_intelligence_records(environment_id,record_id),CHECK((project_delete_after IS NULL)<>(indefinite_basis IS NULL)),CHECK(hard_source_delete_after IS NULL OR indefinite_basis IS NULL),CHECK((declared_parent_count=0 AND parent_head_id IS NULL) OR (declared_parent_count=1 AND parent_head_id IS NOT NULL)),CHECK(corrects_record_id IS NULL OR corrects_record_id=parent_head_id),CHECK(parent_head_id IS NULL OR parent_head_id<>record_id));
CREATE TABLE intelligence_record_parents(environment_id TEXT NOT NULL,child_record_id TEXT NOT NULL,child_stream_id TEXT NOT NULL,child_record_type TEXT NOT NULL,parent_record_id TEXT NOT NULL,parent_stream_id TEXT NOT NULL,parent_record_type TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal=0),PRIMARY KEY(environment_id,child_record_id),UNIQUE(environment_id,parent_record_id),FOREIGN KEY(environment_id,child_record_id,child_stream_id,child_record_type) REFERENCES authenticated_intelligence_records(environment_id,record_id,stream_id,record_type),FOREIGN KEY(environment_id,parent_record_id,parent_stream_id,parent_record_type) REFERENCES authenticated_intelligence_records(environment_id,record_id,stream_id,record_type),CHECK(child_stream_id=parent_stream_id),CHECK(child_record_type=parent_record_type),CHECK(child_record_id<>parent_record_id));
CREATE TABLE intelligence_stream_heads(environment_id TEXT NOT NULL,stream_id TEXT NOT NULL,record_type TEXT NOT NULL,current_record_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),PRIMARY KEY(environment_id,stream_id,record_type),FOREIGN KEY(environment_id,current_record_id,stream_id,record_type) REFERENCES authenticated_intelligence_records(environment_id,record_id,stream_id,record_type));
CREATE TABLE intelligence_head_transitions(environment_id TEXT NOT NULL,transition_id TEXT NOT NULL,stream_id TEXT NOT NULL,record_type TEXT NOT NULL,expected_head_id TEXT,new_record_id TEXT NOT NULL,expected_revision INTEGER NOT NULL,new_revision INTEGER NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(environment_id,transition_id),UNIQUE(environment_id,new_record_id,transition_id),UNIQUE(environment_id,stream_id,record_type,expected_revision),FOREIGN KEY(environment_id,new_record_id,stream_id,record_type) REFERENCES authenticated_intelligence_records(environment_id,record_id,stream_id,record_type),CHECK(new_revision=expected_revision+1),CHECK((expected_head_id IS NULL AND expected_revision=0) OR (expected_head_id IS NOT NULL AND expected_revision>0)));
CREATE TABLE intelligence_record_commits(environment_id TEXT NOT NULL,record_id TEXT NOT NULL,transition_id TEXT NOT NULL,committed_at TEXT NOT NULL,commit_version TEXT NOT NULL CHECK(commit_version='intelligence-record-commit/2'),PRIMARY KEY(environment_id,record_id),FOREIGN KEY(environment_id,record_id,transition_id) REFERENCES intelligence_head_transitions(environment_id,new_record_id,transition_id));
CREATE TABLE intelligence_finalization_receipts(environment_id TEXT NOT NULL,receipt_id TEXT NOT NULL,transition_id TEXT NOT NULL,record_id TEXT NOT NULL,stream_id TEXT NOT NULL,record_type TEXT NOT NULL,revision INTEGER NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(environment_id,receipt_id),UNIQUE(environment_id,transition_id),FOREIGN KEY(environment_id,record_id) REFERENCES intelligence_record_commits(environment_id,record_id),FOREIGN KEY(environment_id,transition_id) REFERENCES intelligence_head_transitions(environment_id,transition_id));
CREATE TABLE intelligence_retention_events(environment_id TEXT NOT NULL,event_id TEXT NOT NULL,record_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('retained','delete_required','deleted','provider_exit')),project_delete_after TEXT,hard_source_delete_after TEXT,occurred_at TEXT NOT NULL,metadata_jcs TEXT NOT NULL CHECK(length(metadata_jcs)<=2048),PRIMARY KEY(environment_id,event_id),FOREIGN KEY(environment_id,record_id) REFERENCES authenticated_intelligence_records(environment_id,record_id));
CREATE INDEX intelligence_retention_record_time ON intelligence_retention_events(environment_id,record_id,occurred_at DESC,event_id DESC);
CREATE TABLE intelligence_quarantine_records(environment_id TEXT NOT NULL,quarantine_id TEXT NOT NULL,record_id TEXT,reason TEXT NOT NULL,metadata_jcs TEXT NOT NULL CHECK(length(metadata_jcs)<=2048),created_at TEXT NOT NULL,PRIMARY KEY(environment_id,quarantine_id));
CREATE TABLE intelligence_audit_events(environment_id TEXT NOT NULL,event_id TEXT NOT NULL,event_type TEXT NOT NULL CHECK(event_type IN('record_appended','record_rehydrated','record_quarantined','deletion_planned','restore_reconciled','key_rotated')),record_id TEXT,occurred_at TEXT NOT NULL,metadata_jcs TEXT NOT NULL CHECK(length(metadata_jcs)<=2048),PRIMARY KEY(environment_id,event_id));
CREATE TABLE intelligence_key_rotations(environment_id TEXT NOT NULL,rotation_id TEXT NOT NULL,expected_key_id TEXT NOT NULL,expected_algorithm TEXT NOT NULL,expected_activates_at TEXT NOT NULL,expected_identity_jcs TEXT NOT NULL,expected_status_event_id TEXT NOT NULL,demotion_event_id TEXT NOT NULL,replacement_key_id TEXT NOT NULL,replacement_activation_event_id TEXT NOT NULL,replacement_algorithm TEXT NOT NULL,replacement_activates_at TEXT NOT NULL,replacement_identity_jcs TEXT NOT NULL,reason_ref TEXT NOT NULL,issuer_ref TEXT NOT NULL,audit_event_id TEXT NOT NULL,occurred_at TEXT NOT NULL,PRIMARY KEY(environment_id,rotation_id),UNIQUE(environment_id,demotion_event_id),UNIQUE(environment_id,replacement_activation_event_id),FOREIGN KEY(environment_id,expected_key_id,demotion_event_id) REFERENCES intelligence_key_status_events(environment_id,key_id,event_id),FOREIGN KEY(environment_id,replacement_key_id,replacement_activation_event_id) REFERENCES intelligence_key_status_events(environment_id,key_id,event_id),FOREIGN KEY(environment_id,audit_event_id) REFERENCES intelligence_audit_events(environment_id,event_id));
CREATE TABLE governed_deletion_authorizations(environment_id TEXT NOT NULL,authorization_id TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,authority_ref TEXT NOT NULL,issued_at TEXT NOT NULL,expires_at TEXT NOT NULL,planning_metadata_jcs TEXT NOT NULL CHECK(length(planning_metadata_jcs)<=2048),PRIMARY KEY(environment_id,authorization_id));
CREATE TRIGGER intelligence_key_event_guard BEFORE INSERT ON intelligence_key_status_events BEGIN SELECT CASE WHEN (NEW.prior_event_id IS NULL)<>(NOT EXISTS(SELECT 1 FROM intelligence_key_status_events e WHERE e.environment_id=NEW.environment_id AND e.key_id=NEW.key_id)) THEN RAISE(ABORT,'key_prior_event_required') END;SELECT CASE WHEN NEW.prior_event_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM intelligence_current_key_status c WHERE c.environment_id=NEW.environment_id AND c.key_id=NEW.key_id AND c.event_id=NEW.prior_event_id AND c.effective_at<NEW.effective_at) THEN RAISE(ABORT,'key_event_out_of_order') END;SELECT CASE WHEN NEW.prior_event_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM intelligence_key_status_events p WHERE p.environment_id=NEW.environment_id AND p.key_id=NEW.key_id AND p.event_id=NEW.prior_event_id AND ((p.status='active' AND NEW.status IN('verify-only','revoked','unavailable')) OR (p.status='verify-only' AND NEW.status='revoked') OR (p.status='unavailable' AND NEW.status IN('active','verify-only','revoked')))) THEN RAISE(ABORT,'invalid_key_transition') END;SELECT CASE WHEN NEW.status='active' AND EXISTS(SELECT 1 FROM intelligence_current_key_status c WHERE c.environment_id=NEW.environment_id AND c.status='active' AND c.key_id<>NEW.key_id) THEN RAISE(ABORT,'multiple_active_keys') END;END;
CREATE TRIGGER intelligence_rotation_guard BEFORE INSERT ON intelligence_key_rotations BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM intelligence_keys old_key JOIN intelligence_key_status_events old_event ON old_event.environment_id=old_key.environment_id AND old_event.key_id=old_key.key_id JOIN intelligence_current_key_status old_status ON old_status.environment_id=old_key.environment_id AND old_status.key_id=old_key.key_id JOIN intelligence_keys new_key ON new_key.environment_id=NEW.environment_id AND new_key.key_id=NEW.replacement_key_id JOIN intelligence_key_status_events new_event ON new_event.environment_id=new_key.environment_id AND new_event.key_id=new_key.key_id JOIN intelligence_current_key_status new_status ON new_status.environment_id=new_key.environment_id AND new_status.key_id=new_key.key_id WHERE old_key.environment_id=NEW.environment_id AND old_key.key_id=NEW.expected_key_id AND old_key.algorithm=NEW.expected_algorithm AND old_key.activates_at=NEW.expected_activates_at AND old_key.identity_jcs=NEW.expected_identity_jcs AND old_event.event_id=NEW.demotion_event_id AND old_event.prior_event_id=NEW.expected_status_event_id AND old_event.reason_ref=NEW.reason_ref AND old_event.issuer_ref=NEW.issuer_ref AND old_status.event_id=NEW.demotion_event_id AND old_status.status='verify-only' AND new_event.event_id=NEW.replacement_activation_event_id AND new_event.reason_ref=NEW.reason_ref AND new_event.issuer_ref=NEW.issuer_ref AND new_status.event_id=NEW.replacement_activation_event_id AND new_status.status='active' AND new_key.algorithm=NEW.replacement_algorithm AND new_key.activates_at=NEW.replacement_activates_at AND new_key.identity_jcs=NEW.replacement_identity_jcs) THEN RAISE(ABORT,'key_rotation_finalization_failed') END;END;
CREATE TRIGGER intelligence_transition_guard BEFORE INSERT ON intelligence_head_transitions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM authenticated_intelligence_records r WHERE r.environment_id=NEW.environment_id AND r.record_id=NEW.new_record_id AND r.stream_id=NEW.stream_id AND r.record_type=NEW.record_type AND ((NEW.expected_head_id IS NULL AND r.declared_parent_count=0 AND NOT EXISTS(SELECT 1 FROM intelligence_stream_heads h WHERE h.environment_id=NEW.environment_id AND h.stream_id=NEW.stream_id AND h.record_type=NEW.record_type)) OR (NEW.expected_head_id IS NOT NULL AND r.declared_parent_count=1 AND r.parent_head_id=NEW.expected_head_id AND EXISTS(SELECT 1 FROM intelligence_stream_heads h WHERE h.environment_id=NEW.environment_id AND h.stream_id=NEW.stream_id AND h.record_type=NEW.record_type AND h.current_record_id=NEW.expected_head_id AND h.revision=NEW.expected_revision)))) THEN RAISE(ABORT,'head_transition_conflict') END;END;
CREATE TRIGGER intelligence_commit_complete BEFORE INSERT ON intelligence_record_commits BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM authenticated_intelligence_records r JOIN intelligence_head_transitions t ON t.environment_id=r.environment_id AND t.new_record_id=r.record_id AND t.transition_id=NEW.transition_id WHERE r.environment_id=NEW.environment_id AND r.record_id=NEW.record_id AND r.declared_parent_count=(SELECT COUNT(*) FROM intelligence_record_parents p WHERE p.environment_id=r.environment_id AND p.child_record_id=r.record_id)) THEN RAISE(ABORT,'intelligence_incomplete_record') END;SELECT CASE WHEN EXISTS(WITH RECURSIVE ancestry(record_id,depth) AS (SELECT NEW.record_id,0 UNION SELECT p.parent_record_id,a.depth+1 FROM ancestry a JOIN intelligence_record_parents p ON p.environment_id=NEW.environment_id AND p.child_record_id=a.record_id WHERE a.depth<17) SELECT 1 FROM ancestry WHERE (record_id=NEW.record_id AND depth>0) OR depth>16) THEN RAISE(ABORT,'intelligence_ancestry_invalid') END;END;
CREATE TRIGGER intelligence_head_insert_guard BEFORE INSERT ON intelligence_stream_heads BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM intelligence_record_commits c JOIN intelligence_head_transitions t ON t.environment_id=c.environment_id AND t.transition_id=c.transition_id WHERE c.environment_id=NEW.environment_id AND c.record_id=NEW.current_record_id AND t.expected_head_id IS NULL AND t.stream_id=NEW.stream_id AND t.record_type=NEW.record_type AND NEW.revision=t.new_revision) THEN RAISE(ABORT,'intelligence_head_scope_conflict') END;END;
CREATE TRIGGER intelligence_head_update_guard BEFORE UPDATE ON intelligence_stream_heads BEGIN SELECT CASE WHEN NEW.environment_id<>OLD.environment_id OR NEW.stream_id<>OLD.stream_id OR NEW.record_type<>OLD.record_type OR NOT EXISTS(SELECT 1 FROM intelligence_record_commits c JOIN intelligence_head_transitions t ON t.environment_id=c.environment_id AND t.transition_id=c.transition_id WHERE c.environment_id=NEW.environment_id AND c.record_id=NEW.current_record_id AND t.stream_id=NEW.stream_id AND t.record_type=NEW.record_type AND t.expected_head_id=OLD.current_record_id AND t.expected_revision=OLD.revision AND t.new_revision=NEW.revision) THEN RAISE(ABORT,'intelligence_head_scope_conflict') END;END;
CREATE TRIGGER intelligence_receipt_guard BEFORE INSERT ON intelligence_finalization_receipts BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM intelligence_head_transitions t JOIN intelligence_stream_heads h ON h.environment_id=t.environment_id AND h.stream_id=t.stream_id AND h.record_type=t.record_type WHERE t.environment_id=NEW.environment_id AND t.transition_id=NEW.transition_id AND t.new_record_id=NEW.record_id AND t.stream_id=NEW.stream_id AND t.record_type=NEW.record_type AND t.new_revision=NEW.revision AND h.current_record_id=NEW.record_id AND h.revision=NEW.revision) THEN RAISE(ABORT,'head_finalization_failed') END;END;
CREATE TRIGGER no_parent_after_commit BEFORE INSERT ON intelligence_record_parents WHEN EXISTS(SELECT 1 FROM intelligence_record_commits c WHERE c.environment_id=NEW.environment_id AND c.record_id=NEW.child_record_id) BEGIN SELECT RAISE(ABORT,'immutable_intelligence_history');END;
